    SI = solid_SI(x, pH, pe)
    absent = [s for s in range(NSOL) if s not in present]
    changed = False
    for k in sorted(absent, key=lambda s: -SI[s]):
        if SI[k] <= 1e-8:
            break
        # phase rule: is the candidate's stoichiometry (over the 6 free components)
        # linearly dependent on the present solids?  If so, swap instead of add.
        newset = present + [k]
        if np.linalg.matrix_rank(ASM[newset]) < len(newset):
            for p in present:
                alt = [s for s in present if s != p] + [k]
                if np.linalg.matrix_rank(ASM[alt]) == len(alt):
